import { ArrowDown, ArrowUp, ArrowUpDown } from "lucide-react";
import type { ComponentProps, ReactNode } from "react";
import { cn } from "./lib/cn";
import "./shared/bulk-bar.css";
import "./shared/chip-option.css";
import "./data-table.css";

export type DataTableProps = ComponentProps<"table"> & {
  caption: string;
};

export function DataTable({
  caption,
  className,
  children,
  ...props
}: DataTableProps) {
  return (
    <div
      role="region"
      aria-label={`${caption}, scrollable table`}
      tabIndex={0}
      className="relative min-w-0 overflow-x-auto focus-visible:outline-solid focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring"
    >
      <table
        data-slot="data-table"
        className={cn("w-full border-collapse text-start text-sm", className)}
        {...props}
      >
        <caption className="sr-only">{caption}</caption>
        {children}
      </table>
    </div>
  );
}

export function DataTableHead({
  className,
  scope = "col",
  numeric = false,
  sort,
  onSort,
  children,
  ...props
}: ComponentProps<"th"> & {
  /** Right-aligned with tabular figures, for money and counts. */
  numeric?: boolean;
  /** Makes the header a sort button. */
  sort?: "ascending" | "descending" | "none";
  onSort?: () => void;
}) {
  const Icon = sort === "ascending" ? ArrowUp : sort === "descending" ? ArrowDown : ArrowUpDown;
  return (
    <th
      scope={scope}
      aria-sort={sort}
      className={cn(
        "border-b border-border px-3 text-start first:ps-4 last:pe-4",
        scope === "row"
          ? "py-[var(--row-padding)] align-middle text-sm font-normal"
          : "h-11 text-xs font-medium text-muted-foreground",
        numeric && "text-end tabular-nums",
        className,
      )}
      {...props}
    >
      {onSort ? (
        <button type="button" data-slot="sort-button" onClick={onSort} className={cn("inline-flex items-center gap-1 rounded-[4px] outline-none hover:text-foreground focus-visible:outline-solid focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring", numeric && "flex-row-reverse")}>
          {children}
          <Icon aria-hidden="true" className={cn("size-3.5", sort === "none" && "opacity-50")} />
        </button>
      ) : (
        children
      )}
    </th>
  );
}

export function DataTableCell({
  className,
  numeric = false,
  ...props
}: ComponentProps<"td"> & { numeric?: boolean }) {
  return (
    <td
      className={cn(
        "border-b border-border px-3 py-[var(--row-padding)] align-middle first:ps-4 last:pe-4",
        numeric && "text-end tabular-nums",
        className,
      )}
      {...props}
    />
  );
}

/** A row with a quiet hover fill, an ember-tinted selected state and a keyboard cursor. */
export function DataTableRow({
  selected,
  cursor,
  className,
  ...props
}: ComponentProps<"tr"> & { selected?: boolean; cursor?: boolean }) {
  return (
    <tr
      data-slot="data-table-row"
      aria-selected={selected}
      data-cursor={cursor || undefined}
      className={className}
      {...props}
    />
  );
}

/** Rises from the bottom while rows are selected: the count, the total and actions for all of them. */
export function DataTableBulkBar({
  count,
  summary,
  children,
  className,
}: {
  count: number;
  summary?: ReactNode;
  children: ReactNode;
  className?: string;
}) {
  return (
    <div role="toolbar" aria-label="Bulk actions" data-slot="bulk-bar" data-open={count > 0} aria-hidden={count === 0 || undefined} className={className}>
      <span className="text-sm font-medium tabular-nums" aria-live="polite">
        {count} selected{summary ? <> · {summary}</> : null}
      </span>
      {children}
    </div>
  );
}

import { clsx, type ClassValue } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

const twMerge = extendTailwindMerge({
  extend: { theme: { radius: ["control", "surface", "overlay"], shadow: ["overlay"] } },
});

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/* Shared by data-table.tsx, team-members.tsx; each imports it. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="bulk-bar"] {
    position: sticky;
    bottom: 16px;
    z-index: 5;
    display: flex;
    width: fit-content;
    max-width: calc(100% - 16px);
    margin: 12px auto 0;
    align-items: center;
    gap: 8px;
    padding: 6px 6px 6px 14px;
    border-radius: var(--radius-surface);
    background: var(--primary);
    color: var(--primary-foreground);
    box-shadow: var(--shadow-overlay);
    transition:
      translate 320ms var(--ease-settle),
      opacity var(--duration-normal) var(--ease-out);
  }
  [data-slot="bulk-bar"][data-open="false"] {
    translate: 0 24px;
    opacity: 0;
    pointer-events: none;
    visibility: hidden;
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="bulk-bar"] {
      transition: none;
    }
  }
  [data-slot="bulk-bar"] { display: flex; flex-wrap: wrap; align-items: center; gap: 0.75rem; padding: 0.5rem 0.75rem; border: 1px solid var(--border); border-radius: var(--radius-control); background: var(--surface); animation: think-in var(--duration-normal) var(--ease-out) both; }
  @media (prefers-reduced-motion: reduce) { [data-slot="bulk-bar"] { animation: none; } }
}

/* Shared by calendar.tsx, chart-parts.tsx, chip-group.tsx, data-table.tsx, number-field.tsx, password-field.tsx, stepper.tsx; each imports it. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  /* Depth sets 2 and 3 end */

  /* Press feedback (2026-10-20, motion audit): every pressable control answers a press. Compact controls take the
     system press scale, as Button does; wide rows deepen their fill instead, since scaling a full-width row reads as a
     jump. Disabled controls stay still. */
  :is([data-slot="chip-option"], [data-slot="number-field"] button, [data-slot="password-toggle"], [data-slot="calendar"] button, [data-slot="chart-legend-item"], [data-slot="sort-button"], [data-slot="stepper"] button):active:not(:disabled):not([aria-disabled="true"]) {
    scale: var(--motion-press-scale);
  }
}

/* data-table.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="data-table"] tbody tr {
    transition: background-color var(--duration-fast) var(--ease-out);
  }

  /* Data table rows: quiet hover, ember-tinted selection, a keyboard cursor. */
  [data-slot="data-table-row"] > * {
    transition: background-color var(--duration-fast) var(--ease-out);
  }
  @media (hover: hover) {
    [data-slot="data-table-row"]:hover > * {
      background: var(--muted);
    }
  }
  [data-slot="data-table-row"][aria-selected="true"] > * {
    background: var(--selected);
  }
  [data-slot="data-table-row"][data-cursor] > :first-child {
    box-shadow: inset 2px 0 0 var(--foreground);
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="data-table"] tbody tr {
      transition: none;
    }
  }
  [data-slot="sort-button"] {
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
    margin-inline-start: -0.375rem;
    padding: 0.25rem 0.375rem;
    border-radius: var(--radius-control);
    font: inherit;
    color: inherit;
    outline: none;
    transition:
      background-color var(--duration-fast) var(--ease-out),
      color var(--duration-fast) var(--ease-out);
  }
  [data-slot="sort-button"][data-align="end"] {
    margin-inline: auto -0.375rem;
    flex-direction: row-reverse;
  }
  [data-slot="sort-button"]:hover,
  [data-slot="sort-button"][data-active="true"] {
    color: var(--foreground);
  }
  [data-slot="sort-button"]:hover {
    background: var(--muted);
  }
  [data-slot="sort-button"]:focus-visible {
    outline: 2px solid var(--ring);
    outline-offset: 1px;
  }
  @media (prefers-reduced-motion: no-preference) {
    [data-slot="data-table-row"][aria-selected="true"] > * { animation: caliper-select-in var(--duration-normal) var(--ease-out) both; }
  }
}
